// Package uuid validates the textual UUID form accepted by the HTTP contract.
//
// The platform does not depend on a UUID library: identifiers are generated by
// `crypto/rand` in identity and by PostgreSQL elsewhere. This package only
// answers "could this string be a UUID", so a malformed path or body value is
// rejected as a typed validation error instead of reaching PostgreSQL and
// surfacing as an internal error.
package uuid

// Valid reports whether raw is the canonical 8-4-4-4-12 hexadecimal form.
//
// Uppercase hex is accepted (PostgreSQL accepts it too); the value is not
// rewritten, because comparisons happen on the uuid type, not on text.
func Valid(raw string) bool {
	if len(raw) != 36 {
		return false
	}
	for index := 0; index < len(raw); index++ {
		char := raw[index]
		switch index {
		case 8, 13, 18, 23:
			if char != '-' {
				return false
			}
		default:
			if !isHex(char) {
				return false
			}
		}
	}
	return true
}

func isHex(char byte) bool {
	switch {
	case char >= '0' && char <= '9':
		return true
	case char >= 'a' && char <= 'f':
		return true
	case char >= 'A' && char <= 'F':
		return true
	default:
		return false
	}
}
